package com.eventpulse.service;
import com.eventpulse.exception.ValidationException; import com.eventpulse.model.UserProfile; import com.eventpulse.repository.UserRepository; import java.time.Instant;
public class UserService { private final UserRepository repository; public UserService(UserRepository r){repository=r;} public UserProfile get(String id){return get(id,null,null,false);} public UserProfile get(String id,String email,String name,boolean admin){UserProfile u=repository.findById(id).orElseGet(UserProfile::new);u.setUserId(id);if(email!=null&&!email.isBlank())u.setEmail(email);if(name!=null&&!name.isBlank())u.setName(name);if(u.getEmail()==null)u.setEmail("");if(u.getName()==null)u.setName("");u.setRole(admin?"ADMIN":"USER");if(u.getCreatedAt()==null)u.setCreatedAt(Instant.now().toString());return repository.save(u);} }
